CREATE TABLE IF NOT EXISTS options ( -- 选项表
  row_id INTEGER PRIMARY KEY, -- 行号
  slot_type TEXT NOT NULL CHECK(slot_type IN ('交涉', 'NTR', '反抗', '调查', '日常', '危机', '系统', '觉醒', 'tips')), -- 槽位类型
  emoji TEXT NOT NULL DEFAULT '', -- 表情
  option_text TEXT NOT NULL CHECK(LENGTH(option_text) <= 1200) -- 选项文本
);
